sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.wrm-pulse {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-card);
  padding: 16px 18px;
}

.wrm-pulse-head {
  display: flex; align-items: baseline; gap: 12px;
  flex-wrap: wrap; margin-bottom: 12px;
}
.wrm-pulse-head .line { font-size: 14px; color: var(--ink); }
.wrm-pulse-head .key { font-size: 11px; color: var(--ink-3); margin-left: auto; }

.wrm-pulse-bars {
  display: grid;
  grid-template-columns: repeat(10, 1fr);
  gap: 6px;
  align-items: end;
  height: 58px;
}
.wrm-pulse-bars .col { height: 100%; display: flex; align-items: flex-end; }
.wrm-pulse-bars .bar {
  display: block; width: 100%;
  background: var(--free-fg);
  opacity: .32;
  border-radius: 3px 3px 0 0;
}
.wrm-pulse-bars .bar.today { opacity: .6; background: var(--clay); }

.wrm-pulse-labels {
  display: grid;
  grid-template-columns: repeat(10, 1fr);
  gap: 6px;
  margin-top: 6px;
}
.wrm-pulse-labels .col { text-align: center; }
.wrm-pulse-labels .wd { display: block; font-size: 9px; letter-spacing: .06em; color: var(--ink-3); }
.wrm-pulse-labels .dn { display: block; font-size: 10px; color: var(--ink-3); }
.wrm-pulse-labels .col.today .wd,
.wrm-pulse-labels .col.today .dn { color: var(--clay); }

sp_widget.script:
(function() {

  var WEEKDAYS = ['SUN','MON','TUE','WED','THU','FRI','SAT'];
  var HOLDING = 'pending_check_in,checked_in';

  var todayYmd = new GlideDateTime().getDisplayValue().split(' ')[0];
  var tp = todayYmd.split('-');
  var todayUtc = Date.UTC(+tp[0], +tp[1] - 1, +tp[2]);

  function ymd(ms) {
    var d = new Date(ms);
    var m = d.getUTCMonth() + 1;
    var day = d.getUTCDate();
    return d.getUTCFullYear() + '-' +
           (m < 10 ? '0' + m : m) + '-' +
           (day < 10 ? '0' + day : day);
  }

  // The next ten weekdays, starting today. Weekends are skipped
  // rather than shown empty — nobody books a desk on Sunday.
  var days = [];
  var cursor = todayUtc;
  while (days.length < 10) {
    var d = new Date(cursor);
    var dow = d.getUTCDay();
    if (dow !== 0 && dow !== 6) {
      days.push({
        ymd:     ymd(cursor),
        weekday: WEEKDAYS[dow],
        dayNum:  ('0' + d.getUTCDate()).slice(-2),
        isToday: ymd(cursor) === todayYmd,
        booked:  0
      });
    }
    cursor += 86400000;
  }

  var firstYmd = days[0].ymd;
  var lastYmd  = days[days.length - 1].ymd;

  // Total bookable spaces, so the bars mean something.
  var ws = new GlideRecord('x_1903615_worksp_0_workspace_options');
  ws.addQuery('status', '!=', 'decommissioned');
  ws.addQuery('status', '!=', 'under_maintenance');
  ws.query();
  var totalSpaces = ws.getRowCount() || 1;

  // Count reservations touching each day.
  var res = new GlideRecord('x_1903615_worksp_0_reservation_tracker');
  res.addQuery('reservation_status', 'IN', HOLDING);
  res.query();

  while (res.next()) {
    var sDisp = res.getDisplayValue('work_start');
    var eDisp = res.getDisplayValue('work_end');
    if (!sDisp || !eDisp) continue;

    var sYmd = sDisp.split(' ')[0];
    var eYmd = eDisp.split(' ')[0];
    if (eYmd < firstYmd || sYmd > lastYmd) continue;

    for (var i = 0; i < days.length; i++) {
      if (sYmd <= days[i].ymd && eYmd >= days[i].ymd) {
        days[i].booked++;
      }
    }
  }

  // Height as a percentage of the busiest day, so the chart uses
  // its full range rather than hugging the floor.
  var peak = 0;
  for (var j = 0; j < days.length; j++) {
    if (days[j].booked > peak) peak = days[j].booked;
  }

  var quietest = null;
  for (var k = 0; k < days.length; k++) {
    days[k].pct = peak > 0 ? Math.round((days[k].booked / peak) * 100) : 0;
    // A visible stub even on an empty day.
    if (days[k].pct < 8) days[k].pct = 8;

    days[k].occupancy = Math.round((days[k].booked / totalSpaces) * 100);

    if (!quietest || days[k].booked < quietest.booked) quietest = days[k];
  }

  data.days = days;

  // Only worth naming a quietest day if the days actually differ.
  data.headline = '';
  if (peak > 0 && quietest) {
    var full = { MON:'Monday', TUE:'Tuesday', WED:'Wednesday',
                 THU:'Thursday', FRI:'Friday' };
    data.headline = (full[quietest.weekday] || quietest.weekday) +
                    ' the ' + parseInt(quietest.dayNum, 10) + ' is the quietest day coming up.';
  } else {
    data.headline = 'Nothing is booked over the next two weeks.';
  }

})();
